styles:
.b-showcase-page-tools {
    max-width: var(--site-container-width);
    margin: 0 auto;
    padding: var(--site-space-6) var(--site-gutter);
}

.b-showcase-page-tools__heading {
    margin: 0 0 var(--site-space-2);
}

.b-showcase-page-tools__note {
    margin: 0 0 var(--site-space-4);
    color: var(--site-color-text-muted);
}

.b-showcase-page-tools--narrow .b-showcase-page-tools__frame {
    max-width: 20rem;
    padding: var(--site-space-3);
    border: 1px dashed var(--site-color-border);
}

.b-showcase-page-tools__cards {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(10rem, 1fr));
    gap: var(--site-space-4);
    margin: 0;
    padding: 0;
    list-style: none;
}

.b-showcase-page-tools__card {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 8rem;
    margin: 0;
    border-radius: var(--site-radius-md);
    background: var(--site-color-surface);
    font-weight: 600;
}
